package com.fitconnect.payment.api; import com.fitconnect.payment.domain.*; import java.math.BigDecimal; import java.time.LocalDateTime; public record PaymentResponse(Long id,String paymentReference,Long bookingId,String bookingReference,Long userId,BigDecimal amount,PaymentMethod paymentMethod,String cardLastFour,String transactionId,LocalDateTime paymentDate,PaymentStatus status){public static PaymentResponse from(Payment p){return new PaymentResponse(p.getId(),p.getPaymentReference(),p.getBookingId(),p.getBookingReference(),p.getUserId(),p.getAmount(),p.getPaymentMethod(),p.getCardLastFour(),p.getTransactionId(),p.getPaymentDate(),p.getStatus());}}
